        attempts,
        repairLimit: limit,
        repairExhausted: exhausted,
        resumeAttempts,
        resumeLimit,
        lastAction: delivery ? { action: delivery.action, at: delivery.created_at, mutation: delivery.mutation ?? "unknown" } : null,
